"use client";

import { usePathname } from "next/navigation";
import EmployeeSidebar from "@/components/EmployeeSidebar";
import { useState, useEffect, useRef } from "react";
import { Menu } from "lucide-react";
import { getUnreadNotificationsCount } from "@/app/actions/approvals";
import { getUnreadNotifications } from "@/app/actions/notifications";
import { getUnreadCount as getUnreadMailCount } from "@/app/actions/mail";
import { MAIL_UNREAD_EVENT } from "@/lib/mailBadge";
import { getCurrentPermissions } from "@/app/actions/sessionSync";
import FloatingHeader from "@/components/FloatingHeader";

import DeveloperRoleSwitcher from "@/components/DeveloperRoleSwitcher";

export default function DashboardLayoutClient({ children, session, unreadRequests: initial = 0, unreadMails: initialMails = 0 }: { children: React.ReactNode, session: any, unreadRequests?: number, unreadMails?: number }) {
  const pathname = usePathname();
  // Mobile drawer only — the desktop rail is pinned open and no longer reads
  // this. It starts closed, which is also what a phone should show on load.
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [unreadRequests, setUnreadRequests] = useState(initial);
  const [unreadMails, setUnreadMails] = useState(initialMails);

  /**
   * The live role and permissions, replacing the layout's frozen copy.
   *
   * A layout does not re-render on client navigation, so `session` here is a
   * snapshot from the last full page load. Granting a permission changed
   * nothing on screen until the person reloaded — which is why it looked like
   * you had to log out and back in.
   */
  const [liveAccess, setLiveAccess] = useState<{ role: string; permissions: string[] } | null>(null);
  const [appNotificationsData, setAppNotificationsData] = useState<{notifications: any[], count: number}>({ notifications: [], count: 0 });
  const seenNotificationIds = useRef<Set<string>>(new Set());

  // Close sidebar on mobile when navigating
  useEffect(() => {
    if (typeof window !== "undefined" && window.innerWidth < 1024) {
      setIsSidebarOpen(false);
    }
  }, [pathname]);

  /**
   * The badge used to be seeded once by the server layout and never touched
   * again. Layouts persist across client navigation, so reading every message
   * left the old number sitting in the sidebar until a full page reload.
   *
   * Two triggers cover it: every navigation (so it is right the moment you
   * leave the mail screen) and an event the mail screen fires when it marks
   * something read (so it is right while you are still on it).
   *
   * `alive` matters more than it looks: navigating twice quickly starts two
   * requests, and without the guard the slower one can land last and paint a
   * count that was already out of date when it was asked for.
   */
  useEffect(() => {
    let alive = true;

    const refresh = async () => {
      try {
        const count = await getUnreadMailCount();
        if (alive) setUnreadMails(count);
      } catch {
        // A failed count leaves the previous badge in place, which is better
        // than blanking it and claiming there is no unread mail.
      }
    };

    void refresh();
    // Permissions too: a change made while you were on another screen shows
    // up on your next click rather than on your next login.
    void (async () => {
      try {
        const access = await getCurrentPermissions();
        if (alive && access) setLiveAccess(access);
      } catch {
        // Keep whatever the menu already shows; the server re-checks anyway.
      }
    })();
    window.addEventListener(MAIL_UNREAD_EVENT, refresh);

    return () => {
      alive = false;
      window.removeEventListener(MAIL_UNREAD_EVENT, refresh);
    };
  }, [pathname]);

  // polling للإشعارات كل 60 ثانية (يتوقف إذا كان التبويب في الخلفية)
  useEffect(() => {
    let active = true;
    async function poll() {
      if (document.hidden) return;
      try {
        const count = await getUnreadNotificationsCount();
        if (active) setUnreadRequests(count);

        // Same 60s tick as the approvals badge: cheap, and it keeps the mail
        // count honest even if a message is read in another tab.
        const mailCount = await getUnreadMailCount();
        if (active) setUnreadMails(mailCount);

        const access = await getCurrentPermissions();
        if (active && access) setLiveAccess(access);

        const appNotifsRes = await getUnreadNotifications();
        if (active && appNotifsRes && !appNotifsRes.error) {
          setAppNotificationsData({ notifications: appNotifsRes.notifications || [], count: appNotifsRes.count || 0 });
          if ("Notification" in window && Notification.permission === "granted") {
            const notifs = appNotifsRes.notifications || [];
            
            // Get seen notifications from localStorage to persist across reloads
            const storedSeenStr = localStorage.getItem('seen_notifications');
            const isFirstTime = storedSeenStr === null;
            const storedSeen = JSON.parse(storedSeenStr || '[]');
            const seenSet = new Set(storedSeen);
            
            notifs.forEach((n: any) => {
              if (n.isRead) return; // Don't notify for already read notifications
              
              if (!seenSet.has(n.id) && !seenNotificationIds.current.has(n.id)) {
                seenNotificationIds.current.add(n.id);
                seenSet.add(n.id);
                
                // Send push notification only if it's not the first time initializing the local storage
                if (!isFirstTime) {
                  const notification = new Notification(n.title, {
                    body: n.message || "",
                    icon: "/favicon.ico",
                  });
                  notification.onclick = () => {
                    window.focus();
                    notification.close();
                  };
                }
              }
            });
            
            // Save the last 100 seen IDs to localStorage
            localStorage.setItem('seen_notifications', JSON.stringify(Array.from(seenSet).slice(-100)));
            
          } else {
             const notifs = appNotifsRes.notifications || [];
             notifs.forEach((n: any) => seenNotificationIds.current.add(n.id));
          }
        }
      } catch {}
    }
    
    if (!document.hidden) poll();
    
    const interval = setInterval(poll, 60000);
    
    const handleVisibilityChange = () => {
      if (!document.hidden) poll();
    };
    document.addEventListener("visibilitychange", handleVisibilityChange);
    
    return () => { 
      active = false; 
      clearInterval(interval); 
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, []);

  useEffect(() => {
    if (typeof window !== "undefined" && "Notification" in window) {
      if (Notification.permission === "default") {
        Notification.requestPermission();
      }
    }
  }, []);

  return (
    <div className="flex h-[100dvh] bg-slate-50 dark:bg-slate-950 overflow-hidden print:h-auto print:overflow-visible print:block" dir="rtl">


      {/* The session object with its permissions and role replaced by whatever
          the server last said. Everything else about it — id, name, avatar —
          does not change under you mid-visit. */}
      <EmployeeSidebar
        session={liveAccess ? { ...session, ...liveAccess } : session}
        isOpen={isSidebarOpen}
        setIsOpen={setIsSidebarOpen}
        unreadRequests={unreadRequests}
        unreadMails={unreadMails}
      />
      
      <div className="flex-1 flex flex-col min-w-0 h-full overflow-hidden relative print:overflow-visible print:h-auto print:block">
        {/* Desktop top bar.

            Was a floating pill at top-4 left-8, which overlapped whatever was
            underneath it — the mail toolbar had to reserve 200px of dead space
            just to dodge it. As a flex sibling above <main> it occupies its own
            row instead, so nothing has to make room for it and no offset needs
            keeping in sync. */}
        <div className="hidden lg:flex h-14 shrink-0 items-center justify-end gap-2 px-6 bg-white/80 dark:bg-slate-900/80 backdrop-blur-lg border-b border-slate-200/80 dark:border-slate-800/80 z-30 print:hidden">
          <FloatingHeader
            session={session}
            appNotifications={appNotificationsData}
            className="flex items-center gap-2"
          />
        </div>

        {/* Mobile Header (Sticky & Blur) */}
        <div className="lg:hidden sticky top-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-lg border-b border-slate-200/80 dark:border-slate-800/80 h-16 flex items-center justify-between px-4 shrink-0 z-30 shadow-sm print:hidden">
          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsSidebarOpen(true)} 
              className="p-2 -mr-2 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors active:scale-95"
            >
              <Menu className="w-6 h-6" />
            </button>
            <span className="font-bold text-slate-800 dark:text-slate-100 text-lg">لوحة التحكم</span>
          </div>
          <FloatingHeader 
            session={session} 
            appNotifications={appNotificationsData} 
            className="flex items-center gap-1"
          />
        </div>
        
        {/* Main Content Area */}
        <main className="flex-1 overflow-y-auto w-full p-4 sm:p-6 lg:p-8 pb-8 safe-bottom print:overflow-visible print:p-0 print:block">
          <div className="max-w-[1600px] mx-auto w-full">
            {children}
          </div>
        </main>
      </div>

      {session?.isDeveloper && <DeveloperRoleSwitcher currentEmployeeId={session.originalId ? session.id : undefined} hideCharityClients={true} />}
    </div>
  );
}
